// Main runs repoctx with args containing the command and its flags. It exits
// the process for command-line usage or execution errors, matching the
// historical cmd/repoctx behavior.
func Main(args []string) {
	if len(args) < 1 {
		usage()
		os.Exit(2)
	}
	switch args[0] {
	case "overview", "files", "search", "read", "discover":
		discoveryCmd(args[0], args[1:])
	case "compile":
		compileCmd(args[1:])
	case "artifacts":
		artifactsCmd(args[1:])
	case "manifest":
		manifestCmd(args[1:])
	case "stats":
		statsCmd(args[1:])
	case "context":
		contextCmd(args[1:])
	case "validate":
		validateCmd(args[1:])
	case "graph":
		graphCmd(args[1:])
	case "version", "--version":
		versionCmd(args[1:])
	case "help", "-h", "--help":
		usage()
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", args[0])
		usage()
		os.Exit(2)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, `repoctx - compile Go/Python/HTML/CSS/JavaScript/TypeScript/TSX/Markdown repositories into a compact typed IR

Usage:
  repoctx discover [-root DIR] [-query TASK] [-max-bytes 32768]
  repoctx overview [-root DIR] [-depth 2]
  repoctx files [-root DIR] [-glob '*.go'] [-type file|directory|all]
  repoctx search [-root DIR] -query TEXT [-regex] [-context-lines 3]
  repoctx read [-root DIR] -file PATH[:START:END] [-file PATH...]
  repoctx compile [-root DIR] [-manifest FILE] [-o repo.ir.json.gz] [-pretty] [-cache-dir DIR]
  repoctx artifacts -source FILE [-root DIR] [-o FILE] [-check]
  repoctx manifest [-root DIR] [-file agent-context.yaml]
  repoctx stats REPO_IR
  repoctx graph [-match TEXT|-node ID] [-depth N] REPO_IR
  repoctx context -root DIR -query TEXT [-max-bytes 32768] REPO_IR
  repoctx validate REPO_IR
  repoctx version [-format text|json]

Discovery commands need no index or external search tools. They honor local
ignore rules and caller scope. Use COMMAND -help for visibility and budget flags.

The IR contains normalized Tree-sitter AST node tables for Python, HTML, CSS,
JavaScript, TypeScript, TSX and Markdown plus the native Go AST, stable symbols, source-linked occurrence edges,
and a dense forward/reverse CSR symbol graph. Repository symbols occupy graph node
IDs 0..len(symbols)-1; unit/module/unresolved nodes follow them. Tree-sitter
lowering is syntax-only: it does not execute code, type-check, or model embedded
browser languages.`)
}

