 86	// Compile validates artifact authoring, resolves its exact source anchors, and
 87	// returns both the canonical authoring declarations and derived catalog. It
 88	// performs no provider activation, authority resolution, or command execution.
 89	func Compile(root string, data []byte, limits Limits, permit PathPermit) (*Compilation, error) {
 90		doc, normalized, err := decodeAuthoring(data, limits)
