 95		if err != nil {
 96			return nil, err
 97		}
 98		catalog, err := authoringCatalog(doc, anchors, placeholderSpan)
 99		if err != nil {
100			return nil, err
101		}
102		if err := validateGenerated(catalog, normalized); err != nil {
103			return nil, err
104		}
105	
106		sources, err := sourceroot.Open(root)
107		if err != nil {
108			return nil, fmt.Errorf("open source root: %w", err)
109		}
110		defer sources.Close()
111		cache := make(map[string][]byte)
112		resolved := make(map[string]Span, len(doc.SourceAnchors))
113		for _, anchor := range doc.SourceAnchors {
114			if permit != nil && !permit(anchor.Path) {
115				return nil, fmt.Errorf("source anchor %q: path is outside caller scope", anchor.ID)
116			}
117			content, ok := cache[anchor.Path]
118			if !ok {
