131			}
132			resolved[anchor.ID] = span
133		}
134		catalog, err = authoringCatalog(doc, anchors, func(anchor NamedSourceAnchor) Span {
135			return resolved[anchor.ID]
136		})
137		if err != nil {
138			return nil, err
139		}
140		if err := validateGenerated(catalog, normalized); err != nil {
