 16			Depth: 2, ContextLines: 3, MaxBytes: 32768, MaxSourceBytes: 2 << 20,
 17			MaxReadBytes: 256 << 20, MaxResults: 100, MaxEntries: 100000,
 18			AllowPaths: []string{}, DenyPaths: []string{}, Reads: []ReadRequest{},
