 32	func normalize(o Options) (Options, error) {
 33		defaults := DefaultOptions()
 34		if o.Root == "" {
 35			o.Root = defaults.Root
 36		}
 37		if o.Operation == "" {
 38			o.Operation = defaults.Operation
 39		}
 40		if o.Type == "" {
 41			o.Type = defaults.Type
 42		}
 43		if o.Format == "" {
 44			o.Format = defaults.Format
 45		}
 46		if o.MaxBytes == 0 {
 47			o.MaxBytes = defaults.MaxBytes
 48		}
 49		if o.MaxSourceBytes == 0 {
 50			o.MaxSourceBytes = defaults.MaxSourceBytes
 51		}
 52		if o.MaxReadBytes == 0 {
 53			o.MaxReadBytes = defaults.MaxReadBytes
 54		}
 55		if o.MaxResults == 0 {
 56			o.MaxResults = defaults.MaxResults
 57		}
 58		if o.MaxEntries == 0 {
 59			o.MaxEntries = defaults.MaxEntries
 60		}
 61		if o.MaxBytes < 1 || o.MaxSourceBytes < 1 || o.MaxReadBytes < 1 {
 62			return o, invalid("byte limits must be positive")
 63		}
 64		if o.MaxResults < 1 || o.MaxEntries < 1 || o.MaxEntries > 10000000 {
 65			return o, invalid("positive result/entry limits required; max-entries must be <= 10000000")
 66		}
 67		if o.Depth < 0 || o.ContextLines < 0 {
 68			return o, invalid("depth and context lines must be nonnegative")
 69		}
 70		if o.Format != "json" && o.Format != "markdown" {
 71			return o, invalid("format must be json or markdown")
 72		}
 73		if o.Type != "file" && o.Type != "directory" && o.Type != "all" {
 74			return o, invalid("type must be file, directory, or all")
 75		}
 76		switch o.Operation {
 77		case "overview", "files":
 78			if o.Query != "" {
 79				return o, invalid("query is only supported by search/discover")
 80			}
 81		case "search":
 82			if o.Query == "" {
 83				return o, invalid("search requires a nonempty query")
 84			}
 85			if o.Regex {
 86				if _, err := regexp.Compile(o.Query); err != nil {
 87					return o, invalid("invalid regex: %v", err)
 88				}
 89			}
 90		case "read":
 91			if len(o.Reads) == 0 {
 92				return o, invalid("read requires at least one file")
 93			}
 94			if o.Query != "" {
 95				return o, invalid("read does not accept a query")
 96			}
 97		case "discover":
 98		default:
 99			return o, invalid("unknown discovery operation %q", o.Operation)
100		}
101		if o.Operation != "search" && (o.Regex || o.IgnoreCase) {
102			return o, invalid("regex and ignore-case are search options")
103		}
104		if o.Operation != "read" && len(o.Reads) != 0 {
105			return o, invalid("file requests require read")
106		}
107		if o.Operation == "read" && o.Glob != "" {
108			return o, invalid("read does not accept glob filters")
109		}
110		if o.Glob != "" {
111			if _, err := globRegexp(o.Glob); err != nil {
112				return o, invalid("invalid glob: %v", err)
113			}
114		}
115		for _, r := range o.Reads {
116			if !safePath(r.Path) {
117				return o, invalid("unsafe read path %q", r.Path)
118			}
119			if r.StartLine < 0 || r.EndLine < 0 || (r.EndLine > 0 && r.EndLine < r.StartLine) {
120				return o, invalid("invalid line range for %q", r.Path)
121			}
122		}
123		o.AllowPaths = append([]string{}, o.AllowPaths...)
124		o.DenyPaths = append([]string{}, o.DenyPaths...)
125		o.Reads = append([]ReadRequest{}, o.Reads...)
126		for _, prefixes := range [][]string{o.AllowPaths, o.DenyPaths} {
127			for i, p := range prefixes {
128				p = strings.TrimSuffix(p, "/")
129				if !safePath(p) || strings.ContainsAny(p, "*?[") {
130					return o, invalid("invalid scope prefix %q", p)
131				}
132				prefixes[i] = p
133			}
134		}
135		abs, err := filepath.Abs(o.Root)
136		if err != nil {
137			return o, err
138		}
139		o.Root = abs
140		return o, nil
141	}
