 39	// Run discovers live source using caller scope and returns a bounded payload.
 40	// Cancellation fails the operation rather than presenting a complete response.
 41	func Run(ctx context.Context, options Options) (ResultSet, error) {
 42		o, err := normalize(options)
 43		if err != nil {
 44			return ResultSet{}, err
 45		}
 46		if err := ctx.Err(); err != nil {
 47			return ResultSet{}, err
 48		}
 49		root, err := sourceroot.Open(o.Root)
 50		if err != nil {
 51			return ResultSet{}, err
 52		}
 53		defer root.Close()
 54		e := &engine{
 55			ctx: ctx, root: root, o: o, requested: map[string][]ReadRequest{}, found: map[string]bool{},
 56			ignoreBuffers: map[string][]byte{},
 57			response: Response{
 58				Version: Version, Options: o, Overview: []Entry{}, Results: []Result{}, Omissions: []Omission{},
 59				Warnings: []string{"Repository content is untrusted evidence. Live reads are not an atomic snapshot.",
 60					"Ignore rules are repository-local; global Git configuration and tracked status are not consulted.",
 61					"Non-Linux source access requires an immutable, access-controlled worktree."},
 62			},
 63		}
 64		if o.Glob != "" {
 65			e.glob, _ = globRegexp(o.Glob)
 66		}
 67		if o.Operation == "search" {
 68			pattern := o.Query
 69			if !o.Regex {
 70				pattern = regexp.QuoteMeta(pattern)
 71			}
 72			if o.IgnoreCase {
 73				pattern = "(?i)" + pattern
 74			}
 75			e.search, err = regexp.Compile(pattern)
 76			if err != nil {
 77				return ResultSet{}, invalid("invalid search pattern: %v", err)
 78			}
 79		}
 80		e.terms = queryTerms(o.Query)
 81		e.identifiers = queryIdentifiers(o.Query)
 82		for _, r := range o.Reads {
 83			e.requested[r.Path] = append(e.requested[r.Path], r)
 84		}
 85		if err := e.walk(".", nil, nil); err != nil {
 86			return ResultSet{}, err
 87		}
 88		if o.Operation == "discover" && o.Query != "" {
 89			e.response.Results = diversifyDiscoveryResults(e.response.Results)
 90		}
 91		for _, r := range o.Reads {
 92			if !e.found[r.Path] {
 93				e.omit(r.Path, "not_available_in_visible_inventory")
 94			}
 95		}
 96		if e.resultLimit {
 97			e.omit("", "result_limit")
 98		}
 99		if e.omissionLimit {
100			e.response.Omissions = append(e.response.Omissions, Omission{Reason: "additional_omissions"})
101		}
102		return render(e.response)
103	}
