105	// diversifyDiscoveryResults gives broad, bounded discovery responses a small
106	// coverage prefix without admitting weak matches. The first pass retains the
107	// best result from each answer-bearing content class; the second retains the
108	// best result from distinct files. Everything else keeps its original rank.
109	func diversifyDiscoveryResults(results []Result) []Result {
110		if len(results) < 2 || results[0].Score.DistinctTerms < diversityMinTopTerms {
111			return results
112		}
113	
114		minTerms := (results[0].Score.DistinctTerms + 1) / 2
115		limit := min(diversityPrefixLimit, len(results))
116		selected := make([]bool, len(results))
117		prefix := make([]Result, 0, limit)
118		classes := make(map[string]struct{}, 3)
119		paths := make(map[string]struct{}, limit)
120		selectResult := func(i int) {
121			selected[i] = true
122			prefix = append(prefix, results[i])
123			paths[results[i].Path] = struct{}{}
124		}
125		class := func(result Result) string {
126			if result.Candidate == "" {
127				return "source"
128			}
129			return result.Candidate
130		}
131	
132		for i, result := range results {
133			if len(prefix) == limit || result.Score.DistinctTerms < minTerms {
134				break
135			}
136			kind := class(result)
137			if _, ok := classes[kind]; ok {
138				continue
139			}
140			classes[kind] = struct{}{}
141			selectResult(i)
142		}
143		for i, result := range results {
144			if len(prefix) == limit || result.Score.DistinctTerms < minTerms {
145				break
146			}
147			if selected[i] {
148				continue
149			}
150			if _, ok := paths[result.Path]; ok {
151				continue
152			}
153			selectResult(i)
154		}
155		for i, result := range results {
156			if !selected[i] {
157				prefix = append(prefix, result)
158			}
159		}
160		return prefix
161	}
