163	func (e *engine) omit(p, reason string) {
164		e.response.Incomplete = true
165		if len(e.response.Omissions) >= e.o.MaxResults {
166			e.omissionLimit = true
167			return
168		}
169		item := Omission{Path: p, Reason: reason}
170		for _, old := range e.response.Omissions {
171			if old == item {
172				return
173			}
174		}
175		e.response.Omissions = append(e.response.Omissions, item)
176	}
