178	func (e *engine) read(p string) ([]byte, string) {
179		if b, ok := e.ignoreBuffers[p]; ok {
180			return b, ""
181		}
182		remaining := e.o.MaxReadBytes - e.response.Usage.ReadBytes
183		if remaining <= 0 {
184			return nil, "read_limit"
185		}
186		limit := min(e.o.MaxSourceBytes, remaining)
187		b, err := e.root.Read(p, limit)
188		if err != nil {
189			if errors.Is(err, fs.ErrNotExist) {
190				return nil, "not_found_or_changed"
191			}
192			if strings.Contains(err.Error(), "limit") {
193				if remaining < e.o.MaxSourceBytes {
194					return nil, "read_limit"
195				}
196				return nil, "source_limit"
197			}
198			return nil, "unreadable_or_unsafe"
199		}
200		e.response.Usage.ReadBytes += int64(len(b))
201		if bytes.IndexByte(b, 0) >= 0 {
202			return nil, "binary_content"
203		}
204		if !utf8.Valid(b) {
205			return nil, "invalid_utf8"
206		}
207		return b, ""
208	}
