210	func (e *engine) ignoreRules(dir, name string) []rule {
211		p := path.Join(dir, name)
212		if !permitted(p, e.o) {
213			e.omit("", "ignore_rules_outside_scope")
214			return nil
215		}
216		// Resolve these exact filenames independently of enumeration: a truncated
217		// directory listing must not accidentally disable its ignore rules.
218		b, reason := e.read(p)
219		if reason == "not_found_or_changed" {
220			return nil
221		}
222		if reason != "" {
223			e.omit(p, "ignore_"+reason)
224			return nil
225		}
226		e.ignoreBuffers[p] = b
227		rules, err := parseRules(dir, b)
228		if err != nil {
229			e.omit(p, "invalid_ignore_pattern")
230			return nil
231		}
232		return rules
233	}
