235	func (e *engine) walk(dir string, gitRules, localRules []rule) error {
236		if err := e.ctx.Err(); err != nil {
237			return err
238		}
239		remaining := e.o.MaxEntries - e.response.Usage.Entries
240		if remaining <= 0 {
241			e.omit("", "scan_limit")
242			return nil
243		}
244		entries, err := e.root.ReadDir(dir, remaining+1)
245		if err != nil && !errors.Is(err, io.EOF) {
246			if dir == "." {
247				return err
248			}
249			e.omit(dir, "directory_unreadable_or_changed")
250			return nil
251		}
252		if len(entries) > remaining {
253			entries = entries[:remaining]
254			e.omit("", "scan_limit")
255		}
256		e.response.Usage.Entries += len(entries)
257		sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
258		if !e.o.NoIgnore {
259			gitRules = append(append([]rule{}, gitRules...), e.ignoreRules(dir, ".gitignore")...)
260			localRules = append(append([]rule{}, localRules...), e.ignoreRules(dir, ".ignore")...)
261		}
262		rules := append(append([]rule{}, gitRules...), localRules...)
263		for _, item := range entries {
264			if err := e.ctx.Err(); err != nil {
265				return err
266			}
267			name := item.Name()
268			p := path.Join(dir, name)
269			if name == ".git" {
270				continue
271			}
272			if !safePath(p) {
273				e.omit("", "unsupported_path")
274				continue
275			}
276			if !traversable(p, e.o) {
277				continue
278			}
