    32	func render(response Response) (ResultSet, error) {
    33		marked := false
    34		for {
    35			payload, err := serialize(response)
    36			if err != nil {
    37				return ResultSet{}, err
    38			}
    39			if len(payload) <= response.Options.MaxBytes {
    40				return ResultSet{Response: response, Payload: payload}, nil
    41			}
    42			if !marked {
    43				response.Incomplete = true
    44				response.Omissions = append(response.Omissions, Omission{Reason: "output_limit"})
    45				marked = true
    46			}
    47			// Preserve evidence ahead of overview decoration. Never slice serialized
    48			// bytes or silently turn a full requested range into a prefix.
    49			if len(response.Overview) > 0 {
    50				response.Overview = response.Overview[:len(response.Overview)-1]
    51				continue
    52			}
    53			if len(response.Results) > 0 {
    54				response.Results = response.Results[:len(response.Results)-1]
    55				continue
    56			}
    57			if len(response.Omissions) > 1 {
    58				response.Omissions = []Omission{{Reason: "output_limit"}}
    59				continue
    60			}
    61			return ResultSet{}, fmt.Errorf("max-bytes cannot fit discovery response metadata")
    62		}
    63	}
