    17	func discoveryCmd(operation string, args []string) {
    18		ctx, cancel := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
    19		defer cancel()
    20		if err := runDiscovery(ctx, operation, args); err != nil {
    21			if errors.Is(err, flag.ErrHelp) {
    22				return
    23			}
    24			fmt.Fprintln(os.Stderr, err)
    25			var usage *discovery.UsageError
    26			if errors.As(err, &usage) {
    27				os.Exit(2)
    28			}
    29			os.Exit(1)
    30		}
