    33	func runDiscovery(ctx context.Context, operation string, args []string) error {
    34		o := discovery.DefaultOptions()
    35		o.Operation = operation
    36		fs := flag.NewFlagSet(operation, flag.ContinueOnError)
    37		fs.StringVar(&o.Root, "root", o.Root, "selected root; never expands to a parent Git root")
    38		fs.StringVar(&o.Format, "format", o.Format, "json or markdown (same discovery contract)")
    39		fs.BoolVar(&o.Hidden, "hidden", false, "include hidden entries, except .git")
    40		fs.BoolVar(&o.NoIgnore, "no-ignore", false, "disable local ignore rules; never bypass scope")
    41		var allows, denies repeated
    42		fs.Var(&allows, "allow", "permitted relative file/directory prefix; repeat; not a glob")
    43		fs.Var(&denies, "deny", "denied relative file/directory prefix; repeat; deny wins")
    44		fs.IntVar(&o.MaxBytes, "max-bytes", o.MaxBytes, "maximum final serialized payload bytes")
    45		fs.Int64Var(&o.MaxSourceBytes, "max-source-bytes", o.MaxSourceBytes, "maximum bytes per file")
    46		fs.Int64Var(&o.MaxReadBytes, "max-read-bytes", o.MaxReadBytes, "maximum total source and ignore-file bytes")
    47		fs.IntVar(&o.MaxResults, "max-results", o.MaxResults, "maximum result records")
    48		fs.IntVar(&o.MaxEntries, "max-entries", o.MaxEntries, "maximum directory entries enumerated (up to 10000000)")
    49		out := fs.String("o", "-", "output file or - for stdout; no index or cache is created")
    50		if operation == "overview" || operation == "discover" {
    51			fs.IntVar(&o.Depth, "depth", o.Depth, "overview depth; 0 omits the tree (inventory still scanned)")
    52		}
    53		if operation == "search" || operation == "discover" {
    54			fs.StringVar(&o.Query, "query", "", "search pattern or discover task text")
    55			fs.IntVar(&o.ContextLines, "context-lines", o.ContextLines, "surrounding lines per matching line")
    56		}
    57		if operation == "files" || operation == "search" || operation == "discover" {
    58			fs.StringVar(&o.Glob, "glob", "", "path glob; slashless patterns match basenames; ** crosses directories")
    59		}
    60		if operation == "files" {
    61			fs.StringVar(&o.Type, "type", o.Type, "file, directory, or all")
    62		}
    63		if operation == "search" {
    64			fs.BoolVar(&o.Regex, "regex", false, "interpret query as Go regular expression (line-by-line)")
    65			fs.BoolVar(&o.IgnoreCase, "ignore-case", false, "case-insensitive search")
    66		}
    67		var reads repeated
    68		if operation == "read" {
    69			fs.Var(&reads, "file", "PATH or PATH:START:END (inclusive lines); repeat; 0 means start/end")
    70		}
    71		if err := fs.Parse(args); err != nil {
    72			if errors.Is(err, flag.ErrHelp) {
    73				return err
    74			}
    75			return &discovery.UsageError{Message: err.Error()}
    76		}
    77		if fs.NArg() != 0 {
    78			return &discovery.UsageError{Message: "unexpected positional arguments; use named flags"}
    79		}
    80		o.AllowPaths, o.DenyPaths = allows, denies
    81		for _, value := range reads {
    82			parts := strings.Split(value, ":")
    83			r := discovery.ReadRequest{Path: parts[0]}
    84			if len(parts) != 1 {
    85				if len(parts) != 3 {
    86					return &discovery.UsageError{Message: "file must be PATH or PATH:START:END"}
    87				}
    88				var startErr, endErr error
    89				r.StartLine, startErr = strconv.Atoi(parts[1])
    90				r.EndLine, endErr = strconv.Atoi(parts[2])
    91				if startErr != nil || endErr != nil {
    92					return &discovery.UsageError{Message: "invalid file line range"}
    93				}
    94			}
    95			o.Reads = append(o.Reads, r)
    96		}
    97		result, err := discovery.Run(ctx, o)
    98		if err != nil {
    99			return err
   100		}
   101		return writePayload(*out, result.Payload)
   102	}
